{"command": "cd ~; python3 - <<'EOF'
import workcell
def touch(y, z0=98.4, zmin=90):
    workcell.call("arm","move","550",str(y),"105")
    workcell.call("arm","move","550",str(y),str(z0))
    f=workcell.call("ft","read","200","--json").data
    if f["fz"]>0.3: print(y,"contact already at",z0,f); workcell.call("arm","move","550",str(y),"105"); return
    while True:
        r=workcell.call("arm","step","-0.3","--json")
        if not r.ok: print(r.text); break
        if r.data["fz_N"]>0.3 or r.data["z_mm"]<zmin:
            print(y, r.text.splitlines()[0]); break
    workcell.call("arm","move","550",str(y),"105")
for y in [20, 30, 36, 40]:
    touch(y)
EOF"}

